cuda_source = """
#include <cuda_fp16.h>

__global__ void depthwise_conv2d_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    half* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int input_height,
    const int input_width,
    const int output_height,
    const int output_width,
    const int kernel_size,
    const int stride,
    const int padding
) {
    const int batch_idx = blockIdx.x;
    const int channel_idx = blockIdx.y;
    const int output_h_idx = threadIdx.x;
    const int output_w_idx = threadIdx.y;

    if (batch_idx >= batch_size || channel_idx >= in_channels ||
        output_h_idx >= output_height || output_w_idx >= output_width) {
        return;
    }

    const int input_offset = batch_idx * in_channels * input_height * input_width +
                            channel_idx * input_height * input_width;

    const int weight_offset = channel_idx * kernel_size * kernel_size;

    const int output_offset = batch_idx * in_channels * output_height * output_width +
                             channel_idx * output_height * output_width;

    // Each thread computes one output element
    const int out_h = output_h_idx;
    const int out_w = output_w_idx;

    half sum = __float2half(0.0f);

    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            const int ih = out_h * stride + kh - padding;
            const int iw = out_w * stride + kw - padding;

            if (ih >= 0 && ih < input_height && iw >= 0 && iw < input_width) {
                const int input_idx = input_offset + ih * input_width + iw;
                const int weight_idx = weight_offset + kh * kernel_size + kw;

                sum = __hadd(sum, __hmul(input[input_idx], weight[weight_idx]));
            }
        }
    }

    const int output_idx = output_offset + out_h * output_width + out_w;
    output[output_idx] = sum;
}

// Wrapper function to launch kernel
extern "C" void launch_depthwise_conv2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding
) {
    dim3 grid(batch_size, in_channels);
    dim3 block(output_height, output_width);

    depthwise_conv2d_kernel<<<grid, block>>>(
        input, weight, output,
        batch_size, in_channels, input_height, input_width,
        output_height, output_width, kernel_size, stride, padding
    );
}
"""

# Python wrapper class
class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.bias = bias

        # Initialize weight
        self.weight = torch.nn.Parameter(torch.randn(in_channels, kernel_size, kernel_size, dtype=torch.float16))
        if bias:
            self.bias = torch.nn.Parameter(torch.randn(in_channels, dtype=torch.float16))
        else:
            self.register_parameter('bias', None)

        # Compile CUDA extension
        self.module = load_inline(
            name="depthwise_conv2d_ext",
            cpp_sources="",
            cuda_sources=cuda_source,
            functions=["launch_depthwise_conv2d"],
            verbose=False
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, _, height, width = x.shape

        # Calculate output dimensions
        output_height = (height + 2 * self.padding - self.kernel_size) // self.stride + 1
        output_width = (width + 2 * self.padding - self.kernel_size) // self.stride + 1

        # Prepare output tensor
        output = torch.empty(batch_size, self.in_channels, output_height, output_width, 
                           dtype=torch.float16, device=x.device)

        # Launch CUDA kernel
        self.module.launch_depthwise_conv2d(
            x.contiguous().data_ptr(),
            self.weight.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.in_channels,
            height,
            width,
            output_height,
            output_width,
            self.kernel_size,
            self.stride,
            self.padding
        )

        # Add bias if needed
        if self.bias is not None:
            output += self.bias.view(1, -1, 1, 1)

        return output

